def bounds(self) -> tuple[tuple[Version, bool] | None, tuple[Version, bool] | None]:
    """Return the combined lower and upper bounds of all specifiers.

    Returns a ``(lower, upper)`` tuple where each element is either
    ``None`` (no bound) or a ``(Version, inclusive)`` tuple.

    Raises :exc:`ValueError` if any specifier uses the ``===`` operator.

    .. versionadded:: 26.5
    """
    if self._has_arbitrary:
        raise ValueError("bounds() does not support === specifiers")

    if not self._specs:
        return (None, None)

    lower_ver: Version | None = None
    lower_inc: bool = True
    upper_ver: Version | None = None
    upper_inc: bool = True

    for spec in self._specs:
        op = spec.operator
        ver_str = spec.version

        if op == ">=":
            v = spec._require_spec_version()
            if lower_ver is None or v > lower_ver or (
                v == lower_ver and not True
            ):
                lower_ver, lower_inc = v, True

        elif op == ">":
            v = spec._require_spec_version()
            if lower_ver is None or v > lower_ver or (
                v == lower_ver and not False
            ):
                lower_ver, lower_inc = v, False

        elif op == "<=":
            v = spec._require_spec_version()
            if upper_ver is None or v < upper_ver or (
                v == upper_ver and not True
            ):
                upper_ver, upper_inc = v, True

        elif op == "<":
            v = spec._require_spec_version()
            if upper_ver is None or v < upper_ver or (
                v == upper_ver and not False
            ):
                upper_ver, upper_inc = v, False

        elif op == "==":
            v = spec._require_spec_version()
            if ver_str.endswith(".*"):
                # Wildcard: lower = (V, True), upper = (next_prefix, False)
                if lower_ver is None or v > lower_ver or (
                    v == lower_ver and not True
                ):
                    lower_ver, lower_inc = v, True
                inc_release = (*v.release[:-1], v.release[-1] + 1)
                upper_v = Version.from_parts(epoch=v.epoch, release=inc_release)
                if upper_ver is None or upper_v < upper_ver or (
                    upper_v == upper_ver and not False
                ):
                    upper_ver, upper_inc = upper_v, False
            else:
                # Exact: lower = (V, True), upper = (V, True)
                if lower_ver is None or v > lower_ver or (
                    v == lower_ver and not True
                ):
                    lower_ver, lower_inc = v, True
                if upper_ver is None or v < upper_ver or (
                    v == upper_ver and not True
                ):
                    upper_ver, upper_inc = v, True

        elif op == "~=":
            v = spec._require_spec_version()
            if lower_ver is None or v > lower_ver or (
                v == lower_ver and not True
            ):
                lower_ver, lower_inc = v, True
            # upper: drop last release digit, increment the new last
            prefix_release = v.release[:-1]
            inc_release = (*prefix_release[:-1], prefix_release[-1] + 1)
            upper_v = Version.from_parts(epoch=v.epoch, release=inc_release)
            if upper_ver is None or upper_v < upper_ver or (
                upper_v == upper_ver and not False
            ):
                upper_ver, upper_inc = upper_v, False

        elif op == "!=":
            # No bounds contribution
            pass

    return (
        (lower_ver, lower_inc) if lower_ver is not None else None,
        (upper_ver, upper_inc) if upper_ver is not None else None,
    )
